export const ANALYSIS_TYPE_OPTIONS = ANALYSIS_TYPES.map((value) => ANALYSIS_TYPE_COPY[value]);

export const PHONE_FORMAT_ERROR =
  "Số điện thoại chưa đúng định dạng. Vui lòng kiểm tra và nhập lại.";
export const VEHICLE_FORMAT_ERROR =
  "Biển số chưa đúng định dạng. Vui lòng kiểm tra và nhập lại đầy đủ.";
export const ID_DOCUMENT_FORMAT_ERROR =
  "Số CCCD/Hộ chiếu chưa đúng định dạng. Vui lòng kiểm tra và nhập lại.";
export const MISSING_TYPE_ERROR = "Vui lòng chọn loại số cần phân tích.";
export const STATIC_GOLDEN_SAMPLE_ERROR = "Bản dựng tĩnh hiện chỉ hỗ trợ số mẫu 0328278786.";
export const STATIC_GOLDEN_SAMPLE_NOTE = "Bản dựng tĩnh đang xem trước số mẫu 0328278786.";

type ValidateCustomerInputOptions = {
  runtimeMode?: boolean;
};

const PHONE_SEPARATORS = /[.\s-]/g;
const VEHICLE_SEPARATORS = /[.\s-]/g;
const ID_DOCUMENT_SEPARATORS = /[.\s-]/g;

export function compactPhoneInput(raw: string): string {
  return raw.trim().replace(PHONE_SEPARATORS, "");
}

export function isGoldenPhonePreviewInput(type: AnalysisType, raw: string): boolean {
  return type === "phone_number" && compactPhoneInput(raw) === GOLDEN_PREVIEW_INPUT;
}

export function getAnalysisOption(type: AnalysisType): AnalysisTypeOption {
  return ANALYSIS_TYPE_COPY[type];
}

export function isAnalysisType(value: string): value is AnalysisType {
  return (ANALYSIS_TYPES as readonly string[]).includes(value);
}

export function validateCustomerInput(
  type: AnalysisType | "",
  raw: string,
  options: ValidateCustomerInputOptions = {},
): string | null {
  if (!isAnalysisType(type)) {
    return MISSING_TYPE_ERROR;
  }
  const trimmed = raw.trim();
  if (!trimmed) {
    return ANALYSIS_TYPE_COPY[type].emptyMessage;
  }
  const runtimeMode = options.runtimeMode === true;
  if (type === "phone_number") {
    const compact = compactPhoneInput(trimmed);
    if (!/^\d+$/.test(compact) || !compact.startsWith("0") || compact.length < 9 || compact.length > 11) {
      return PHONE_FORMAT_ERROR;
    }
    if (!runtimeMode && !isGoldenPhonePreviewInput(type, trimmed)) {
      return STATIC_GOLDEN_SAMPLE_ERROR;
    }
    return null;
  }
  if (type === "car_plate") {
    const compactPlate = trimmed.replace(VEHICLE_SEPARATORS, "");
    if (!/^[0-9A-Za-z]+$/.test(compactPlate)) {
      return VEHICLE_FORMAT_ERROR;
    }
    if (runtimeMode) {
      return null;
    }
    return STATIC_GOLDEN_SAMPLE_ERROR;
  }
  const compactIdentity = trimmed.replace(ID_DOCUMENT_SEPARATORS, "");
  if (!/^[0-9A-Za-z]+$/.test(compactIdentity)) {
    return ID_DOCUMENT_FORMAT_ERROR;
  }
  if (runtimeMode) {
    return null;
  }
  return STATIC_GOLDEN_SAMPLE_ERROR;
}
